mapper.select:
SELECT s.id, s.travel_plan_id, s.title, s.start_date, s.end_date,
       s.representative_image_url, s.finalized_at, s.created_at
FROM travel_plan_final_snapshots s
         JOIN travel_plan_final_members m ON m.snapshot_id = s.id
WHERE s.travel_plan_id = #{travelPlanId}
  AND m.user_id = #{userId}
